int Mark(string name, int value) { Print(name); return value; }
class C {
    public int Field = Mark("field", 1);
    public int Count { get; set; } = Mark("property", 2);
    public C() : this(Mark("outer argument", 4)) { Print("outer body"); }
    public C(int n) : this(second: Mark("second argument", n + 1), first: Mark("first argument", n)) { Print("middle body:" + n); }
    private C(int first, long second) : base() { Print("inner body:" + first + ":" + second); }
}
void Main() { var c = new C { Count = Mark("object initializer", 9) }; Print(c.Field); Print(c.Count); }
